const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE = 'fbtq_marketing_workspace_v1';
const ROLE_NAMES = {director:'Giám đốc',branch_manager:'Quản lý chi nhánh',department_manager:'Trưởng phòng',employee:'Nhân viên'};
const state = {user:null,role:'employee',firebase:null,signingUp:false,metrics:[],tasks:[],drafts:[],scripts:[],banned:[],reviews:[],templates:[],requests:[],invoices:[],dailyReports:[],inboxThreads:[],messages:[],activeThread:null,inboxUnsubscribe:null,messageUnsubscribe:null,invoiceUnsubscribe:null,members:[],users:[],pages:[],pageName:'Tổng quan'};
const storeKey=()=>`${STORE}_${state.user?.uid||'guest'}`;
const saveLocal=()=>localStorage.setItem(storeKey(),JSON.stringify({tasks:state.tasks,drafts:state.drafts,scripts:state.scripts,banned:state.banned,invoices:state.invoices,dailyReports:state.dailyReports,theme:document.body.classList.contains('dark')?'dark':'light'}));
function loadLocalForUser(){try{const saved=JSON.parse(localStorage.getItem(storeKey())||'null');if(!saved)return;const demoTaskIds=new Set(['t1','t2','t3','t4','t5','t6','t7','t8']),demoDraftIds=new Set(['d1','d2']),demoScriptTitles=new Set(['Chào khách mới','Tư vấn tình trạng hàng','Chính sách giao hàng']),demoBanned=new Set(['lừa đảo','đảm bảo khỏi','cam kết 100%','chắc chắn có lãi','nhắn tin riêng','số điện thoại cá nhân','tài khoản ngân hàng','bôi nhọ','chửi tục','thông tin cá nhân','giảm cân cấp tốc','trị khỏi']);state.tasks=(saved.tasks||[]).filter(x=>!demoTaskIds.has(String(x.id)));state.drafts=(saved.drafts||[]).filter(x=>!demoDraftIds.has(String(x.id)));state.metrics=[];state.scripts=(saved.scripts||[]).filter(x=>!demoScriptTitles.has(x.title));state.banned=(saved.banned||[]).filter(x=>!demoBanned.has(x));state.invoices=saved.invoices||[];state.dailyReports=saved.dailyReports||[];if(saved.theme)setTheme(saved.theme)}catch{}}
localStorage.removeItem('fbtq_demo_user');localStorage.removeItem(`${STORE}_demo`);localStorage.removeItem(`${STORE}_guest`);
const money = n => new Intl.NumberFormat('vi-VN').format(Number(n)||0) + ' ₫';
const roleName = role => ROLE_NAMES[role] || ROLE_NAMES.employee;
const isManager = () => ['director','branch_manager','department_manager'].includes(state.role);
const isDirector = () => state.role === 'director';
const showToast = (message,type='success') => {const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3600)};
const configFromInputs = () => ({apiKey:$('#fbApiKey').value.trim(),authDomain:$('#fbAuthDomain').value.trim(),projectId:$('#fbProjectId').value.trim(),appId:$('#fbAppId').value.trim()});
const validConfig = c => !!(c?.apiKey && c?.authDomain && c?.projectId && c?.appId);
const getSavedFirebaseConfig = () => {try{return JSON.parse(localStorage.getItem('fbtq_firebase_config')||'null')}catch{return null}};
let firebaseBootPromise=Promise.resolve(false);

async function firebaseInit(config, announce=false) {
  if (!validConfig(config)) return false;
  if(state.firebase){if(announce)showToast('Firebase đã kết nối trong phiên này. Tải lại trang để thay đổi dự án.');return true}
  try {
    const [appMod,authMod,storeMod] = await Promise.all([
      import('https://www.gstatic.com/firebasejs/10.14.1/firebase-app.js'),
      import('https://www.gstatic.com/firebasejs/10.14.1/firebase-auth.js'),
      import('https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore.js')
    ]);
    let funcMod=null;
    try{funcMod=await import('https://www.gstatic.com/firebasejs/10.14.1/firebase-functions.js')}catch(error){console.warn('Firebase Functions chưa tải được; đăng nhập vẫn hoạt động.',error)}
    const app = appMod.getApps().length ? appMod.getApp() : appMod.initializeApp(config);
    const auth = authMod.getAuth(app);
    const db = storeMod.getFirestore(app);
    const functions = funcMod?.getFunctions(app)||null;
    state.firebase = {app,auth,db,functions,authMod,storeMod,funcMod};
    $('#firebaseIndicator').textContent='● Firebase đã kết nối';$('#firebaseIndicator').classList.add('connected');$('#firebaseStatus').textContent='● Firebase đã kết nối';$('#firebaseStatus').className='status status-live';
    authMod.onAuthStateChanged(auth, async user => {
      if (!user) { if (state.user?.uid) signOutToAuth(); return; }
      if(state.signingUp)return;
      if(state.user?.uid&&state.user.uid!==user.uid)signOutToAuth();
      try {
        const userRef=storeMod.doc(db,'users',user.uid);
        const snap=await storeMod.getDoc(userRef);
        let profile=snap.exists()?snap.data():null;
        if(!profile){
          profile={name:user.displayName||user.email||'Nhân viên',email:user.email||'',role:'employee',approved:true};
          await storeMod.setDoc(userRef,{...profile,createdAt:storeMod.serverTimestamp()});
        }
        const token=await user.getIdTokenResult();
        if(state.firebase.auth.currentUser?.uid!==user.uid)return;
        state.user={uid:user.uid,email:user.email,name:profile.name||user.displayName||user.email,department:profile.department||'',role:profile.role||token.claims.role||'employee',approved:true};state.role=state.user.role;enterApp();
      } catch(e){console.error(e);showAuthNotice(authErrorMessage(e))}
    });
    if(announce)showToast('Đã kết nối Firebase. Bật Email/Password và triển khai Firestore Rules.');
    return true;
  } catch(error) {
    console.error(error);if(announce)showToast('Không kết nối được Firebase: '+(error.message||'kiểm tra cấu hình và hosting HTTPS'),'error');return false;
  }
}
async function saveRecord(collection,data,id=crypto.randomUUID()) {
  if(!state.firebase)return id;
  const {db,storeMod}=state.firebase;
  await storeMod.setDoc(storeMod.doc(db,'workspaces','fbtq',collection,id),{...data,updatedAt:storeMod.serverTimestamp(),updatedBy:state.user?.uid||null,createdBy:data.createdBy||state.user?.uid||null},{merge:true});
  return id;
}
async function callFunction(name,data) {
  if(!state.firebase?.funcMod)throw new Error('Dịch vụ Functions chưa kết nối. Đăng nhập vẫn dùng được; quản trị viên cần kiểm tra Firebase Functions.');
  const callable=state.firebase.funcMod.httpsCallable(state.firebase.functions,name);
  const result=await callable(data);return result.data;
}
function signOutToAuth(){for(const key of ['inboxUnsubscribe','messageUnsubscribe','invoiceUnsubscribe'])if(state[key]){state[key]();state[key]=null}state.user=null;state.role='employee';for(const key of ['metrics','tasks','drafts','scripts','banned','reviews','templates','requests','invoices','dailyReports','inboxThreads','messages','members','users','pages'])state[key]=[];state.activeThread=null;$('#app').classList.add('hidden');$('#authScreen').classList.remove('hidden')}
function enterApp(){
  loadLocalForUser();
  $('#authScreen').classList.add('hidden');$('#app').classList.remove('hidden');
  const name=state.user?.name||state.user?.email||'Tài khoản',initials=name.split(/\s+/).filter(Boolean).slice(-2).map(x=>x[0]).join('').toUpperCase()||'NV';
  $('#sideUserName').textContent=name;$('#greetingName').textContent=name.split(/\s+/)[0];$('#sideUserRole').textContent=roleName(state.role);$('#sideAvatar').textContent=initials;$('#topAvatar').textContent=initials;const dateLabel=$('#overviewDate');if(dateLabel)dateLabel.textContent=new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date()).toLocaleUpperCase('vi-VN');
  $$('.admin-only').forEach(el=>el.classList.toggle('hidden',!isDirector()));$$('.manager-only').forEach(el=>el.classList.toggle('hidden',!isManager()));
  $('#taskPermissionHint').classList.toggle('hidden',isManager());
  renderTasks();renderMetrics();renderDrafts();renderTemplates();renderInbox();renderInvoices();renderDailyReports();loadRevenueLeaderboard();renderPeople();renderBotSummaries();renderConnectedPages();renderContentQueuePreview();saveLocal();
  if(state.firebase){loadCloudData();loadRevenueLeaderboard()}
}
async function loadCloudData(){
  try{
    const {db,storeMod}=state.firebase,uid=state.user.uid,ref=name=>storeMod.collection(db,'workspaces','fbtq',name);
    const taskQuery=isManager()?ref('tasks'):storeMod.query(ref('tasks'),storeMod.where('assigneeUid','==',state.user.uid));
    const campaignQuery=isManager()?ref('campaigns'):storeMod.query(ref('campaigns'),storeMod.where('createdBy','==',state.user.uid));
    const draftQuery=isManager()?ref('drafts'):storeMod.query(ref('drafts'),storeMod.where('createdBy','==',state.user.uid));
    const templateQuery=isManager()?ref('contentTemplates'):storeMod.query(ref('contentTemplates'),storeMod.where('status','==','approved'));
    const inboxQuery=storeMod.query(ref('inbox'),storeMod.where('ownerUid','==',state.user.uid));
    const messageQuery=storeMod.query(ref('messages'),storeMod.where('ownerUid','==',state.user.uid));
    const invoiceQuery=isManager()?ref('invoices'):storeMod.query(ref('invoices'),storeMod.where('createdBy','==',state.user.uid));
    const reportQuery=isManager()?ref('dailyReports'):storeMod.query(ref('dailyReports'),storeMod.where('createdBy','==',state.user.uid));
    const requests=[storeMod.getDocs(taskQuery),storeMod.getDocs(campaignQuery),storeMod.getDocs(draftQuery),storeMod.getDocs(templateQuery),storeMod.getDocs(inboxQuery),storeMod.getDocs(messageQuery),storeMod.getDocs(invoiceQuery),storeMod.getDocs(reportQuery)];
    if(isManager()){requests.push(storeMod.getDocs(ref('contentReviews')));requests.push(storeMod.getDocs(storeMod.collection(db,'users')))}
    const snaps=await Promise.all(requests);if(state.user?.uid!==uid)return;
    state.tasks=snaps[0].docs.map(d=>({id:d.id,...d.data()}));state.metrics=snaps[1].docs.map(d=>({id:d.id,...d.data()}));state.drafts=snaps[2].docs.map(d=>({id:d.id,...d.data()}));state.templates=snaps[3].docs.map(d=>({id:d.id,...d.data()}));state.inboxThreads=snaps[4].docs.map(d=>({id:d.id,...d.data()}));state.messages=snaps[5].docs.map(d=>({id:d.id,...d.data()}));state.invoices=snaps[6].docs.map(d=>({id:d.id,...d.data()}));state.dailyReports=snaps[7].docs.map(d=>({id:d.id,...d.data()}));
    state.reviews=isManager()&&snaps[8]?snaps[8].docs.map(d=>({id:d.id,...d.data()})):[];state.users=isManager()&&snaps[9]?snaps[9].docs.map(d=>({uid:d.id,...d.data()})):[];
    const botSnap=await storeMod.getDoc(storeMod.doc(db,'workspaces','fbtq','settings','bot'));if(state.user?.uid!==uid)return;
    state.scripts=[];state.banned=[];
    if(botSnap.exists()){const bot=botSnap.data();state.scripts=Array.isArray(bot.scripts)?bot.scripts:[];state.banned=Array.isArray(bot.banned)?bot.banned:[];if(bot.brandVoice)$('#brandVoice').value=bot.brandVoice;if(bot.defaultModel){$('#defaultModel').value=bot.defaultModel;const radio=$(`input[name="aiModel"][value="${bot.defaultModel}"]`);if(radio){radio.checked=true;$$('.model-choice').forEach(x=>x.classList.toggle('selected',$('input',x)===radio))}}}
    if(state.firebase.funcMod){try{const pageData=await callFunction('listMyPages',{});if(state.user?.uid!==uid)return;state.pages=Array.isArray(pageData.pages)?pageData.pages:[]}catch(error){console.warn('Không tải được danh sách Fanpage.',error);state.pages=[]}}else state.pages=[];renderConnectedPages();renderBotSummaries();
    state.members=state.users.filter(m=>m.approved).map(m=>({uid:m.uid,name:m.name||m.email,initials:(m.name||m.email||'NV').split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase(),tone:'blue'}));
    $('#taskAssigneeFilter').innerHTML='<option value="all">Tất cả nhân viên</option>'+state.members.map(m=>`<option value="${esc(m.name)}">${esc(m.name)}</option>`).join('');
    saveLocal();renderTasks();renderMetrics();renderDrafts();renderTemplates();renderInbox();renderInvoices();renderDailyReports();loadRevenueLeaderboard();renderPeople();renderBotSummaries();renderContentQueuePreview();
    if(state.inboxUnsubscribe)state.inboxUnsubscribe();if(state.messageUnsubscribe)state.messageUnsubscribe();if(state.invoiceUnsubscribe)state.invoiceUnsubscribe();
    state.inboxUnsubscribe=storeMod.onSnapshot(inboxQuery,snapshot=>{state.inboxThreads=snapshot.docs.map(d=>({id:d.id,...d.data()}));renderInbox()});
    state.messageUnsubscribe=storeMod.onSnapshot(messageQuery,snapshot=>{state.messages=snapshot.docs.map(d=>({id:d.id,...d.data()}));if(state.activeThread)selectThread(state.activeThread)});
    state.invoiceUnsubscribe=storeMod.onSnapshot(invoiceQuery,snapshot=>{state.invoices=snapshot.docs.map(d=>({id:d.id,...d.data()}));renderInvoices()});
  }catch(e){console.error(e);showToast('Không tải được dữ liệu từ Firebase. Kiểm tra Firestore Rules.','error')}
}
function renderInbox(){const list=$('.inbox-list');if(!list)return;$$('.conversation',list).forEach(el=>el.remove());const header=$('.chat-header');if(!state.inboxThreads.length){state.activeThread=null;$('.avatar',header).textContent='✦';$('div:nth-child(2) b',header).textContent='Chưa có hội thoại';$('div:nth-child(2) small',header).textContent='Kết nối Fanpage để bắt đầu';$('#chatBody').innerHTML='<div class="result-empty"><h3>Chưa có tin nhắn</h3><p>Hội thoại sẽ xuất hiện sau khi Fanpage được kết nối và webhook nhận dữ liệu.</p></div>';return}state.inboxThreads.sort((a,b)=>(b.receivedAt?.seconds||0)-(a.receivedAt?.seconds||0));state.inboxThreads.forEach((thread,index)=>{const name=thread.senderName||`Khách ${String(thread.senderId||'').slice(-4)}`;const row=document.createElement('div');row.className='conversation'+(index===0?' selected':'');row.dataset.threadId=thread.id;row.innerHTML=`<span class="avatar avatar-lilac">${esc(name.split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase())}</span><div><div class="conversation-head"><b>${esc(name)}</b><small>${thread.receivedAt?.seconds?new Date(thread.receivedAt.seconds*1000).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}):''}</small></div><p>${esc(thread.message||'[Tệp đính kèm]')}</p><span class="channel-tag">${esc(thread.channel||'Messenger')} · ${esc(thread.pageName||'Fanpage')}</span></div>`;row.addEventListener('click',()=>selectThread(thread));list.append(row)});selectThread(state.inboxThreads[0])}
function selectThread(thread){state.activeThread=thread;$$('.conversation').forEach(el=>el.classList.toggle('selected',el.dataset.threadId===thread.id));const name=thread.senderName||`Khách ${String(thread.senderId||'').slice(-4)}`;const header=$('.chat-header');$('.avatar',header).textContent=name.split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase();$('div:nth-child(2) b',header).textContent=name;$('div:nth-child(2) small',header).textContent=`Messenger · ${thread.pageName||'Fanpage'}`;const history=state.messages.filter(m=>m.conversationId===thread.conversationId).sort((a,b)=>(a.createdAt?.seconds||0)-(b.createdAt?.seconds||0));const latestIncoming=[...history].reverse().find(m=>m.direction==='incoming');state.activeMessage=latestIncoming?.message||thread.message;const items=history.length?history:[thread];const bubbles=items.map(m=>{const time=m.createdAt?.seconds?new Date(m.createdAt.seconds*1000).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}):'';return`<div class="message ${m.direction==='outgoing'?'our-message':'customer-msg'}">${esc(m.message||'[Tệp đính kèm]')}<small>${time}</small></div>`}).join('');$('#chatBody').innerHTML=`<div class="chat-date">${thread.receivedAt?.seconds?new Date(thread.receivedAt.seconds*1000).toLocaleDateString('vi-VN',{day:'2-digit',month:'long'}):'Hội thoại'}</div>${bubbles}${latestIncoming?`<div class="ai-suggestion"><div><span class="ai-spark">✦</span><b>Gợi ý trả lời từ AI</b><span class="suggestion-model">${esc(thread.model||'Gemini')}</span></div><p>Chọn “Tạo gợi ý” để AI soạn câu trả lời theo kịch bản đã duyệt.</p><div class="suggestion-actions"><button id="sendSuggestion">✓ Gửi trả lời</button><button id="editSuggestion">✎ Chỉnh sửa</button><button class="regenerate" id="regenerateReply">↻ Tạo gợi ý</button></div></div>`:''}`;bindChatActions();}
function bindChatActions(){const suggest=$('#regenerateReply');suggest?.addEventListener('click',async()=>{if(!state.firebase||!state.activeThread)return showToast('Kết nối Fanpage và Firebase để tạo gợi ý thật.','error');suggest.disabled=true;suggest.textContent='Đang tạo…';try{const result=await callFunction('suggestReply',{pageId:state.activeThread.pageId,message:state.activeMessage,model:state.activeThread.model||'gemini'});$('.ai-suggestion p').textContent=result.content}catch(e){showToast(e.message,'error')}finally{suggest.disabled=false;suggest.textContent='↻ Tạo lại'}});$('#sendSuggestion')?.addEventListener('click',async()=>{const text=$('.ai-suggestion p').textContent;if(text.startsWith('Chọn “Tạo gợi ý”'))return showToast('Tạo gợi ý trước khi gửi.','error');await sendChatReply(text)});$('#editSuggestion')?.addEventListener('click',()=>{const p=$('.ai-suggestion p');p.contentEditable='true';p.focus()})}

// Login and registration
function authErrorMessage(error){const code=error?.code||'';if(code==='auth/unauthorized-domain')return 'Tên miền website chưa được Firebase cho phép. Trong Authentication → Settings → Authorized domains, thêm bighappy9xx.github.io.';if(code==='auth/operation-not-allowed'||code==='auth/configuration-not-found')return 'Firebase chưa bật Email/Password. Vào Authentication → Sign-in method và bật Email/Password.';if(code==='auth/invalid-credential'||code==='auth/wrong-password'||code==='auth/user-not-found')return 'Email hoặc mật khẩu chưa chính xác. Hãy kiểm tra lại hoặc chọn Quên mật khẩu.';if(code==='auth/invalid-email')return 'Địa chỉ email chưa đúng định dạng.';if(code==='auth/weak-password')return 'Mật khẩu chưa đủ mạnh. Hãy dùng ít nhất 8 ký tự.';if(code==='auth/network-request-failed')return 'Không kết nối được Firebase. Hãy kiểm tra mạng và mở website bằng HTTPS.';if(code==='auth/too-many-requests')return 'Firebase tạm khóa thử đăng nhập quá nhiều lần. Hãy đợi một lúc rồi thử lại.';if(code==='permission-denied'||code==='firestore/permission-denied')return 'Firebase đã xác thực nhưng Firestore từ chối tạo/đọc hồ sơ. Hãy triển khai firestore.rules mới.';return error?.message||'Không thể kết nối Firebase. Hãy kiểm tra cấu hình Auth và Firestore.'}function showAuthNotice(message,success=false){const notice=$('#authNotice');notice.textContent=message;notice.classList.toggle('success',success)}
function switchToLogin(message,email,success=false){$('#registerForm').classList.add('hidden');$('#loginForm').classList.remove('hidden');$('#registerNotice').textContent='';if(email)$('#loginForm [name=email]').value=email;showAuthNotice(message,success)}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();showAuthNotice('');if(!state.firebase){showAuthNotice('Đang kết nối Firebase…');await firebaseBootPromise}if(!state.firebase){showAuthNotice('Chưa kết nối được Firebase. Kiểm tra cấu hình, Email/Password và tên miền được phép.');return}const f=new FormData(e.currentTarget);try{await state.firebase.authMod.signInWithEmailAndPassword(state.firebase.auth,f.get('email'),f.get('password'))}catch(err){showAuthNotice(authErrorMessage(err))}});
$('#registerForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form);if(!state.firebase){$('#registerNotice').textContent='Đang kết nối Firebase…';await firebaseBootPromise}if(!state.firebase){$('#registerNotice').textContent='Chưa kết nối được Firebase. Kiểm tra cấu hình, Email/Password và tên miền được phép.';return}state.signingUp=true;try{const {user}=await state.firebase.authMod.createUserWithEmailAndPassword(state.firebase.auth,f.get('email'),f.get('password'));await state.firebase.authMod.updateProfile(user,{displayName:f.get('name')});await state.firebase.storeMod.setDoc(state.firebase.storeMod.doc(state.firebase.db,'users',user.uid),{name:f.get('name'),email:user.email,role:'employee',approved:true,createdAt:state.firebase.storeMod.serverTimestamp()});await state.firebase.authMod.signOut(state.firebase.auth);const email=user.email;form.reset();switchToLogin('Đăng ký thành công. Vui lòng đăng nhập bằng tài khoản vừa tạo.',email,true)}catch(err){if(['auth/email-already-in-use','auth/email-already-exists'].includes(err.code)){switchToLogin('Email này đã được đăng ký. Hãy đăng nhập hoặc chọn “Quên mật khẩu?” nếu bạn quên mật khẩu.',f.get('email'))}else{$('#registerNotice').textContent=err.code==='permission-denied'?'Tài khoản có thể đã được tạo trong Firebase Authentication, nhưng Firestore Rules từ chối lưu hồ sơ. Triển khai firestore.rules rồi thử đăng nhập.':authErrorMessage(err)}}finally{state.signingUp=false}});
$('#showRegister').addEventListener('click',e=>{e.preventDefault();showAuthNotice('');$('#registerNotice').textContent='';$('#loginForm').classList.add('hidden');$('#registerForm').classList.remove('hidden')});$('#showLogin').addEventListener('click',e=>{e.preventDefault();showAuthNotice('');$('#registerNotice').textContent='';$('#registerForm').classList.add('hidden');$('#loginForm').classList.remove('hidden')});
$('.toggle-password').addEventListener('click',e=>{const input=$('input',e.currentTarget.parentElement);input.type=input.type==='password'?'text':'password'});
$('#forgotLink').addEventListener('click',async e=>{e.preventDefault();const email=$('#loginForm [name=email]').value;if(!state.firebase){showAuthNotice('Kết nối Firebase và nhập email để nhận liên kết đặt lại mật khẩu.');return}if(!email){showAuthNotice('Nhập email trước, sau đó bấm Quên mật khẩu.');return}try{await state.firebase.authMod.sendPasswordResetEmail(state.firebase.auth,email);showAuthNotice('Đã gửi liên kết đặt lại mật khẩu nếu email tồn tại.',true)}catch(err){showAuthNotice(err.message)}});
$('#logoutBtn').addEventListener('click',async()=>{if(state.firebase)await state.firebase.authMod.signOut(state.firebase.auth);signOutToAuth()});

// Navigation and common controls
const pageNames={overview:'Tổng quan',analytics:'Hiệu suất marketing',leaderboard:'Xếp hạng & so sánh nhân sự',content:'Tạo content',tasks:'Công việc',automation:'Tự động hoá',inbox:'Chatbot AI',people:'Nhân sự & phân quyền',settings:'Cài đặt hệ thống'};
function navigate(name){if(name==='people'&&!isDirector()){showToast('Chỉ Giám đốc mới có thể quản lý quyền truy cập.','error');return}$$('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===name));$('#crumbPage').textContent=pageNames[name]||name;$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show');window.scrollTo({top:0,behavior:'smooth'})}
$$('.nav-item').forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.page)));$$('[data-goto]').forEach(el=>el.addEventListener('click',()=>navigate(el.dataset.goto)));
$('#mobileMenu').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#sidebarScrim').classList.add('show')});$('#sidebarClose').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show')});$('#sidebarScrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show')});
$('#themeToggle').addEventListener('click',()=>setTheme(document.body.classList.contains('dark')?'light':'dark'));function setTheme(mode){document.body.classList.toggle('dark',mode==='dark');localStorage.setItem(storeKey(),JSON.stringify({...JSON.parse(localStorage.getItem(storeKey())||'{}'),theme:mode}));$$('[data-theme-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.themeChoice===mode))}
$$('[data-theme-choice]').forEach(b=>b.addEventListener('click',()=>setTheme(b.dataset.themeChoice)));
$('#searchTrigger').addEventListener('click',()=>{$('#searchBox').classList.toggle('hidden');if(!$('#searchBox').classList.contains('hidden'))$('input',$('#searchBox')).focus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#searchBox').classList.add('hidden');closeModal()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchBox').classList.remove('hidden');$('input',$('#searchBox')).focus()}});
$$('[data-setting]').forEach(b=>b.addEventListener('click',()=>selectSetting(b.dataset.setting)));function selectSetting(name){$$('[data-setting]').forEach(b=>b.classList.toggle('selected',b.dataset.setting===name));$$('.setting-section').forEach(s=>s.classList.toggle('selected',s.id===`setting-${name}`))}
