  const periodKey=$('#reportPeriodFilter').value,periodRows=state.metrics.filter(item=>reportPeriodKey(item)===periodKey),range=revenueWindowForMetrics(periodRows);
  const measure=user=>{const own=periodRows.filter(item=>item.createdBy===user.uid);const revenue=state.dailyReports.filter(report=>{const date=reportDateKey(report);return report.createdBy===user.uid&&date&&date>=range.start&&date<=range.end}).reduce((sum,report)=>sum+(Number(report.revenue)||0),0);return{spend:own.reduce((sum,item)=>sum+(Number(item.spend)||0),0),revenue,reach:own.reduce((sum,item)=>sum+(Number(item.reach)||0),0),results:own.reduce((sum,item)=>sum+(Number(item.results)||0),0)}};
  const a=measure(userA),b=measure(userB),metrics=[['Doanh thu','revenue',money],['Chi tiêu','spend',money],['Người tiếp cận','reach',value=>Number(value).toLocaleString('vi-VN')],['Kết quả','results',value=>Number(value).toLocaleString('vi-VN')]];
  $('#analyticsCompareCaption').textContent=($('#reportPeriodFilter').selectedOptions[0]?.textContent||'Tháng hiện tại')+' · doanh thu cộng từ báo cáo quảng cáo hằng ngày.';
