$('#openDrafts').addEventListener('click',()=>{navigate('content');$$('[data-editor-tab]').find(x=>x.dataset.editorTab==='drafts').click()});$('#addTemplate').addEventListener('click',()=>{openModal('Đề xuất mẫu nội dung',`<div class="modal-fields">${fInput('Tên mẫu','title','Ví dụ: Ra mắt bộ sưu tập')}${fSelect('Nền tảng','platform',[['Facebook','Facebook'],['Instagram','Instagram'],['TikTok','TikTok'],['Email','Email marketing']])}<label>Nội dung mẫu<textarea name="prompt" placeholder="Mô tả prompt mẫu..."></textarea></label></div>`,'Gửi quản lý duyệt',async f=>{if(state.firebase)await saveRecord('contentTemplates',{title:f.get('title'),platform:f.get('platform'),prompt:f.get('prompt'),status:'pending'});closeModal();showToast('Đã gửi đề xuất mẫu tới quản lý.')})});

// Tasks: only management roles can create or assign. Staff can update own task status.
const taskColumns=[['todo','Chưa bắt đầu'],['doing','Đang làm'],['done','Hoàn thành']];
function taskDate(d){if(!d)return'Chưa đặt';const date=d?.toDate?d.toDate():new Date(d);if(Number.isNaN(date.getTime()))return'—';return date.toLocaleDateString('vi-VN',{day:'2-digit',month:'short'})+' · '+date.toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}
function renderTasks(filter='all'){const assignee=$('#taskAssigneeFilter')?.value||'all';const counts={all:state.tasks.length,todo:state.tasks.filter(t=>t.status==='todo').length,doing:state.tasks.filter(t=>t.status==='doing').length,done:state.tasks.filter(t=>t.status==='done').length};for(const key of Object.keys(counts)){const el=$('#taskCount'+key[0].toUpperCase()+key.slice(1));if(el)el.textContent=counts[key]}$('#taskNavCount').textContent=state.tasks.filter(t=>t.status!=='done').length;$('#taskBoard').innerHTML=taskColumns.map(([status,title])=>{const tasks=state.tasks.filter(t=>t.status===status&&(filter==='all'||filter===status)&&(assignee==='all'||t.assignee===assignee));return`<section class="task-column"><div class="task-column-head"><b>${title}</b><span class="column-count">${tasks.length}</span></div><div class="task-column-list">${tasks.map(t=>`<article class="task-card"><div class="task-card-top"><span class="task-tag">${esc(t.tag||'')}</span>${t.priority==='Cao'?'<span class="priority-label">● Ưu tiên cao</span>':''}</div><h4>${esc(t.title)}</h4><p>${esc(t.description||'')}</p><div class="task-card-foot"><span class="task-assignee"><i class="avatar avatar-${esc(t.tone||'blue')}">${esc(t.initials||'NV')}</i>${esc(t.assignee||'Chưa giao')}</span><span class="${status!=='done'&&t.due&&new Date(t.due)<new Date()?'due-urgent':''}">◷ ${esc(taskDate(t.due))}</span></div><div class="task-card-foot"><span>Giao ${esc(taskDate(t.createdAt))}</span><select data-task-status="${esc(t.id)}" aria-label="Cập nhật trạng thái">${taskColumns.map(([v,l])=>`<option value="${v}" ${v===status?'selected':''}>${l}</option>`).join('')}</select></div></article>`).join('')||'<div class="muted" style="font-size:9px;padding:10px 2px">Không có công việc</div>'}</div></section>`}).join('');const priority=state.tasks.filter(t=>t.status!=='done').sort((a,b)=>String(a.due||'').localeCompare(String(b.due||''))).slice(0,3);$('#priorityTasks').innerHTML=priority.map(t=>`<div class="priority-task"><span class="task-check"></span><div><b>${esc(t.title)}</b><small>${esc(t.assignee||'Chưa giao')} · ${esc(taskDate(t.due))}</small></div></div>`).join('')||'<p class="muted">Chưa có công việc cần ưu tiên.</p>';$$('[data-task-status]').forEach(sel=>sel.addEventListener('change',async()=>{const task=state.tasks.find(t=>t.id===sel.dataset.taskStatus);if(!task)return;if(!isManager()&&task.assigneeUid!==state.user?.uid&&task.assignee!==state.user?.name){showToast('Bạn chỉ có thể cập nhật công việc được giao cho mình.','error');sel.value=task.status;return}task.status=sel.value;saveLocal();try{await saveRecord('tasks',task,task.id)}catch(e){showToast(e.message,'error');return}renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all');showToast('Đã cập nhật trạng thái công việc.')}))}
$('#taskAssigneeFilter').addEventListener('change',()=>renderTasks($('[data-task-filter].selected')?.dataset.taskFilter||'all'));
$$('[data-task-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-task-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderTasks(b.dataset.taskFilter)}));
$('#newTaskBtn').addEventListener('click',()=>{if(!isManager())return showToast('Bạn không có quyền giao công việc.','error');openModal('Giao công việc mới',`<div class="modal-fields">${fInput('Tên công việc','title','Ví dụ: Hoàn thiện báo cáo tuần')}${fInput('Mô tả','description','Mục tiêu và yêu cầu bàn giao', 'text',false)}${fSelect('Người nhận','assignee',state.members.map(m=>[m.uid,m.name]))}${fSelect('Mức ưu tiên','priority',[['Bình thường','Bình thường'],['Cao','Ưu tiên cao'],['Thấp','Thấp']])}<label>Hạn hoàn thành<input type="datetime-local" name="due" required></label>${fSelect('Phân loại','tag',[['Quảng cáo','Quảng cáo'],['Nội dung','Nội dung'],['Báo cáo','Báo cáo'],['Chatbot','Chatbot'],['Thiết kế','Thiết kế'],['Website','Website']])}</div>`,'Giao việc',async f=>{const member=state.members.find(m=>m.uid===f.get('assignee'));const assignee=member?.name||f.get('assignee'),initials=member?.initials||assignee.split(' ').map(x=>x[0]).join('').toUpperCase();const task={id:crypto.randomUUID(),title:f.get('title'),description:f.get('description'),assignee,assigneeUid:member?.uid||'',initials,tone:member?.tone||'blue',status:'todo',due:f.get('due'),priority:f.get('priority'),tag:f.get('tag'),createdAt:new Date().toISOString()};state.tasks.unshift(task);saveLocal();if(state.firebase)await saveRecord('tasks',task,task.id);closeModal();renderTasks();showToast('Đã giao công việc.')})});

// Reports, requests and invoice generation.
function reportDateLabel(value){const key=String(value||'');const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(key);return match?new Date(Number(match[1]),Number(match[2])-1,Number(match[3])).toLocaleDateString('vi-VN'):'—'}
function renderDailyReports(){const body=$('#reportHistoryTable');if(!body)return;const rows=[...state.dailyReports].sort((a,b)=>reportDateKey(b).localeCompare(reportDateKey(a))||String(b.submittedAt||'').localeCompare(String(a.submittedAt||'')));body.innerHTML=rows.map(r=>`<tr><td>${esc(r.employee||r.createdByName||'Nhân viên')}</td><td>${esc(r.campaign||'—')}</td><td>${metricMoney(r.spend)}</td><td>${metricCount(r.results)}</td><td>${money(r.revenue)}</td><td>${esc(reportDateLabel(reportDateKey(r)))}</td><td><span class="status status-live">Đã nộp</span></td></tr>`).join('')||'<tr><td colspan="7" class="muted">Chưa có báo cáo nào được nộp.</td></tr>'}
function openDailyReportForm(){
  if(!state.firebase)return showToast('Hãy kết nối Firebase để đồng bộ báo cáo và bảng xếp hạng.','error');
  const today=new Date(),todayKey=today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');
  openModal('Báo cáo quảng cáo hàng ngày',`<p>Nhập số liệu thực tế của chiến dịch. Doanh thu sẽ được cộng vào KPI và bảng xếp hạng theo ngày báo cáo.</p><div class="modal-fields">${fInput('Ngày báo cáo','reportDate',todayKey,'date')}${fInput('Chiến dịch','campaign','Tên chiến dịch')}${fInput('Chi tiêu (₫)','spend','Số tiền đã chi tiêu','number')}${fInput('Doanh thu (₫)','revenue','Doanh thu trong ngày','number')}${fInput('Hiển thị','impressions','Lượt hiển thị','number')}${fInput('Kết quả','results','Số kết quả','number')}<label>Ghi chú<textarea name="note" placeholder="Nhận xét hoặc đề xuất..."></textarea></label></div>`,'Nộp báo cáo',async f=>{
    const reportDate=String(f.get('reportDate')||''),campaign=f.get('campaign').trim(),spend=Number(f.get('spend')),revenueText=String(f.get('revenue')||'').trim(),revenue=Number(revenueText),impressions=Number(f.get('impressions')),results=Number(f.get('results'));
    if(!/^\d{4}-\d{2}-\d{2}$/.test(reportDate)||!campaign||!revenueText||![spend,revenue,impressions,results].every(value=>Number.isFinite(value)&&value>=0))throw new Error('Nhập ngày, chiến dịch và các chỉ số không âm, gồm cả doanh thu.');
    const uid=state.user.uid,id=uid+'_'+reportDate.replace(/-/g,'')+'_'+stableMetricHash(metricHeaderKey(campaign)).slice(0,12),now=new Date().toISOString(),department=state.user.department||'';
    const record={reportDate,monthKey:reportDate.slice(0,7),campaign,spend,revenue,impressions,results,note:f.get('note').trim(),employee:state.user.name,createdBy:uid,createdByName:state.user.name,department,submittedAt:now};
    const {db,storeMod}=state.firebase,batch=storeMod.writeBatch(db),reportRef=storeMod.doc(db,'workspaces','fbtq','dailyReports',id),revenueRef=storeMod.doc(db,'workspaces','fbtq','revenueEntries',id),metadata={updatedAt:storeMod.serverTimestamp(),updatedBy:uid};
    batch.set(reportRef,{...record,...metadata},{merge:true});batch.set(revenueRef,{reportDate,monthKey:record.monthKey,revenue,dailyReportId:id,createdBy:uid,createdByName:state.user.name,department,submittedAt:now,...metadata},{merge:true});await batch.commit();
    const next={...record,id},existing=state.dailyReports.findIndex(item=>item.id===id);if(existing<0)state.dailyReports.unshift(next);else state.dailyReports[existing]=next;saveLocal();renderDailyReports();renderMetrics();loadRevenueLeaderboard();closeModal();showToast(existing<0?'Đã nộp báo cáo và cộng doanh thu.':'Đã cập nhật báo cáo ngày, doanh thu không bị cộng trùng.');
  });$('#activeModalForm [name="reportDate"]').value=todayKey;$('#activeModalForm [name="reportDate"]').max=todayKey;$$('#activeModalForm input[type="number"]').forEach(input=>{input.min='0';input.step='1'});
}
$('#dailyReportBtn').addEventListener('click',openDailyReportForm);
function invoiceStatus(status){return status==='approved'?['Đã duyệt','status-live']:status==='rejected'?['Từ chối','status-review']:['Chờ duyệt','status-review']}
function invoiceDocumentHtml(invoice){return`<!doctype html><html lang="vi"><meta charset="utf-8"><title>Hoá đơn ${esc(invoice.invoiceNumber||'')}</title><style>body{font:14px Arial;color:#233;padding:48px;max-width:800px;margin:auto}h1{color:#3575ed}table{width:100%;border-collapse:collapse;margin:25px 0}td,th{border:1px solid #ddd;padding:12px;text-align:left}.total{text-align:right;font-size:20px;font-weight:bold}.muted{color:#778}</style><h1>HOÁ ĐƠN</h1><p>Marketing Ai FBTQ · Mã: ${esc(invoice.invoiceNumber||'—')} · Ngày ${esc(invoice.issueDate||'')}</p><hr><p><b>Khách hàng:</b> ${esc(invoice.customer||'—')}<br><b>Mã số thuế:</b> ${esc(invoice.taxId||'—')}</p><table><tr><th>Dịch vụ / sản phẩm</th><th>Số lượng</th><th>Đơn giá</th><th>Thành tiền</th></tr><tr><td>${esc(invoice.item||'—')}</td><td>${Number(invoice.quantity)||0}</td><td>${money(invoice.unitPrice??invoice.price)}</td><td>${money(invoice.total)}</td></tr></table><p class="total">Tổng cộng: ${money(invoice.total)}</p><p>${esc(invoice.note||'')}</p><p style="margin-top:70px">Đại diện FBTQ ____________________</p></html>`}
function downloadApprovedInvoice(id){const invoice=state.invoices.find(x=>x.id===id);if(!invoice||!(invoice.status==='approved'||!invoice.status))return showToast('Chỉ tải được hóa đơn đã được duyệt.','error');downloadFile(`hoa-don-${invoice.invoiceNumber||id}.html`,invoiceDocumentHtml(invoice),'text/html')}
function renderInvoices(){const body=$('#invoiceTable');if(!body)return;const rows=[...state.invoices].sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));body.innerHTML=rows.map(invoice=>{const status=invoice.status||'approved',label=invoiceStatus(status),date=invoice.createdAt?.toDate?invoice.createdAt.toDate().toLocaleDateString('vi-VN'):invoice.createdAt?new Date(invoice.createdAt).toLocaleDateString('vi-VN'):'—';const action=status==='approved'||!invoice.status?`<button class="text-button" data-invoice-download="${esc(invoice.id)}">Tải hóa đơn</button>`:isManager()&&status==='pending'?`<button class="approve-btn" data-invoice-action="approved" data-id="${esc(invoice.id)}">Duyệt</button><button class="reject-btn" data-invoice-action="rejected" data-id="${esc(invoice.id)}">Từ chối</button>`:'—';return`<tr><td><b>${esc(invoice.invoiceNumber||'Đề xuất')}</b><small>${esc(invoice.customer||'')}</small></td><td>${esc(invoice.item||'—')}<small>${Number(invoice.quantity)||0} × ${money(invoice.unitPrice??invoice.price)}</small></td><td>${money(invoice.total)}</td><td>${esc(invoice.createdByName||invoice.employee||'Nhân viên')}<small>${esc(date)}</small></td><td><span class="status ${label[1]}">${label[0]}</span></td><td>${action}</td></tr>`}).join('')||'<tr><td colspan="6" class="muted">Chưa có đề xuất hóa đơn.</td></tr>';const pending=state.invoices.filter(x=>x.status==='pending').length;$('#invoicePendingCount').textContent=pending+' chờ duyệt';$$('[data-invoice-download]').forEach(button=>button.addEventListener('click',()=>downloadApprovedInvoice(button.dataset.invoiceDownload)));$$('[data-invoice-action]').forEach(button=>button.addEventListener('click',()=>updateInvoiceStatus(button.dataset.id,button.dataset.invoiceAction)))}
async function updateInvoiceStatus(id,status){if(!isManager())return showToast('Chỉ trưởng phòng hoặc quản lý mới có thể duyệt hóa đơn.','error');const invoice=state.invoices.find(x=>x.id===id);if(!invoice||invoice.status!=='pending')return;try{const reviewed={...invoice,status,reviewedBy:state.user.uid,reviewedByName:state.user.name,reviewedAt:new Date().toISOString()};await saveRecord('invoices',reviewed,id);state.invoices=state.invoices.map(x=>x.id===id?reviewed:x);saveLocal();renderInvoices();showToast(status==='approved'?'Đã duyệt đề xuất hóa đơn.':'Đã từ chối đề xuất hóa đơn.');if(!$('#modalRoot').innerHTML) return;closeModal();openInvoiceQueue()}catch(e){showToast(e.message||'Không thể cập nhật hóa đơn.','error')}}
async function openInvoiceQueue(){if(!isManager())return showToast('Chỉ trưởng phòng hoặc quản lý mới có thể duyệt hóa đơn.','error');if(state.firebase){try{const snapshot=await state.firebase.storeMod.getDocs(state.firebase.storeMod.collection(state.firebase.db,'workspaces','fbtq','invoices'));state.invoices=snapshot.docs.map(d=>({id:d.id,...d.data()}));renderInvoices()}catch(e){return showToast(e.message,'error')}}const pending=state.invoices.filter(x=>x.status==='pending');const rows=pending.map(invoice=>`<div class="request-row"><span class="template-icon ti-green">▧</span><div><b>${esc(invoice.invoiceNumber||'Đề xuất hóa đơn')} · ${esc(invoice.customer||'')}</b><small>${esc(invoice.item||'')} · ${money(invoice.total)} · ${esc(invoice.createdByName||invoice.employee||'Nhân viên')}</small></div><button type="button" class="approve-btn" data-invoice-queue="approved" data-id="${esc(invoice.id)}">Duyệt</button><button type="button" class="reject-btn" data-invoice-queue="rejected" data-id="${esc(invoice.id)}">Từ chối</button></div>`).join('')||'<p class="muted">Không có hóa đơn nào chờ duyệt.</p>';openModal('Đề xuất hóa đơn',`<p>Kiểm tra thông tin trước khi phê duyệt hoặc từ chối.</p>${rows}`,'',null);$$('[data-invoice-queue]').forEach(button=>button.addEventListener('click',()=>updateInvoiceStatus(button.dataset.id,button.dataset.invoiceQueue)))}
$('#reviewInvoices').addEventListener('click',openInvoiceQueue);
$('#invoiceBtn').addEventListener('click',()=>{openModal('Tạo đề xuất hóa đơn',`<p>Đề xuất sẽ được gửi để trưởng phòng hoặc quản lý phê duyệt. Tệp hóa đơn tải xuống sau khi được duyệt.</p><div class="modal-fields">${fInput('Tên khách hàng','customer','Tên khách hàng / công ty')}${fInput('Mã số thuế (nếu có)','taxId','Mã số thuế','text',false)}${fInput('Dịch vụ / sản phẩm','item','Nội dung hóa đơn')}${fInput('Số lượng','quantity','1','number')}${fInput('Đơn giá (₫)','price','Đơn giá','number')}<label>Ghi chú<textarea name="note" placeholder="Thông tin bổ sung"></textarea></label></div>`,'Gửi quản lý duyệt',async f=>{const quantity=Number(f.get('quantity')),unitPrice=Number(f.get('price')),customer=f.get('customer').trim(),itemName=f.get('item').trim();if(!customer||!itemName||!Number.isInteger(quantity)||quantity<1||!Number.isFinite(unitPrice)||unitPrice<0)throw new Error('Kiểm tra tên khách hàng, dịch vụ, số lượng và đơn giá.');if(!state.firebase)throw new Error('Chưa kết nối Firebase để lưu đề xuất hóa đơn.');const id=crypto.randomUUID(),now=new Date(),invoice={id,invoiceNumber:'FBTQ-'+id.slice(0,8).toUpperCase(),customer,taxId:f.get('taxId').trim(),item:itemName,quantity,unitPrice,total:quantity*unitPrice,note:f.get('note').trim(),issueDate:now.toLocaleDateString('vi-VN'),status:'pending',createdBy:state.user.uid,createdByName:state.user.name,createdAt:now.toISOString()};await saveRecord('invoices',invoice,id);state.invoices.unshift(invoice);saveLocal();renderInvoices();closeModal();showToast('Đã gửi đề xuất hóa đơn để quản lý phê duyệt.') });$('#activeModalForm [name="quantity"]')?.setAttribute('min','1');$('#activeModalForm [name="price"]')?.setAttribute('min','0')});
async function openRequests(){if(!isManager())return showToast('Chỉ quản lý mới có thể duyệt đơn.','error');if(state.firebase){try{const snap=await state.firebase.storeMod.getDocs(state.firebase.storeMod.collection(state.firebase.db,'workspaces','fbtq','requests'));state.requests=snap.docs.map(d=>({id:d.id,...d.data()}))}catch(e){return showToast(e.message,'error')}}const pending=state.requests.filter(r=>r.status==='pending');const rows=pending.length?pending.map(r=>`<div class="request-row"><span class="avatar avatar-peach">${esc((r.employee||'NV').split(/\s+/).map(x=>x[0]).join('').slice(-2))}</span><div><b>${esc(r.employee||'Nhân viên')} · ${esc(r.type||'Yêu cầu')}</b><small>${esc(r.date||'')} · ${esc(r.description||'')}</small></div><button type="button" class="approve-btn" data-request="approve" data-id="${esc(r.id)}">Duyệt</button><button type="button" class="reject-btn" data-request="reject" data-id="${esc(r.id)}">Từ chối</button></div>`).join(''):'<p class="muted">Không có đơn nào đang chờ.</p>';openModal('Đơn cần xử lý',`<p>Yêu cầu nhân viên chờ quản lý xem xét.</p>${rows}`,'',null);$$('[data-request]').forEach(b=>b.addEventListener('click',async()=>{const item=state.requests.find(x=>x.id===b.dataset.id);if(!item)return;const status=b.dataset.request==='approve'?'approved':'rejected';try{if(state.firebase)await saveRecord('requests',{...item,status,reviewedBy:state.user.uid,reviewedAt:new Date().toISOString()},item.id);item.status=status;b.parentElement.style.opacity='.45';b.parentElement.querySelectorAll('button').forEach(x=>x.disabled=true);b.textContent=status==='approved'?'Đã duyệt':'Đã từ chối';showToast(status==='approved'?'Đã duyệt đơn.':'Đã từ chối đơn.')}catch(e){showToast(e.message,'error')}}))}
$('#reviewRequests').addEventListener('click',openRequests);
const requestButton=document.createElement('button');requestButton.className='btn btn-secondary';requestButton.textContent='＋ Gửi yêu cầu';requestButton.addEventListener('click',()=>openModal('Gửi yêu cầu',`<div class="modal-fields">${fSelect('Loại yêu cầu','type',[['Xin nghỉ phép','Xin nghỉ phép'],['Làm việc từ xa','Làm việc từ xa'],['Đề xuất công cụ','Đề xuất công cụ']])}${fInput('Ngày áp dụng','date','', 'date')}${fInput('Mô tả','description','Lý do hoặc thông tin đề xuất')}</div>`,'Gửi quản lý',async f=>{const item={type:f.get('type'),date:f.get('date'),description:f.get('description'),employee:state.user?.name,status:'pending',submittedAt:new Date().toISOString()};if(state.firebase)await saveRecord('requests',item);state.requests.unshift({...item,id:crypto.randomUUID()});closeModal();showToast('Đã gửi yêu cầu cho quản lý.') }));$('#page-automation .page-heading').append(requestButton);

// Chatbot integrations.
$('#botToggle').addEventListener('click',()=>showToast('AI chỉ tạo gợi ý; nhân viên xác nhận trước khi gửi.'));
async function sendChatReply(text){if(!state.firebase||!state.activeThread)return showToast('Kết nối Fanpage và Firebase để trả lời khách hàng.','error');try{await callFunction('sendPageReply',{pageId:state.activeThread.pageId,recipientId:state.activeThread.senderId,message:text});$('#replyInput').value='';showToast('Đã gửi tin nhắn.')}catch(e){showToast(e.message,'error')}}
$('#sendReply').addEventListener('click',async()=>{const text=$('#replyInput').value.trim();if(!text)return;await sendChatReply(text)});$('#replyInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('#sendReply').click()});
function editScripts(){if(!isManager())return showToast('Chỉ quản lý mới có thể chỉnh kịch bản.','error');const content=state.scripts.map((s,i)=>`<div class="draft-row"><span class="template-icon ti-blue">▧</span><div><b>${esc(s.title)}</b><small>${esc(s.text)}</small>${s.image?`<small>✓ Đã đính kèm hình ảnh</small>`:''}</div><button type="button" data-edit-script="${i}">Sửa</button></div>`).join('');openModal('Kịch bản phản hồi',`<p>Quản lý câu trả lời nhanh đã được duyệt. Có thể gắn kịch bản vào Fanpage.</p><div class="draft-list">${content||'Chưa có kịch bản.'}</div><button type="button" class="btn btn-secondary" id="newScript" style="margin-top:12px">＋ Thêm kịch bản</button>`,'',null);$('#newScript').addEventListener('click',()=>editScriptForm());$$('[data-edit-script]').forEach(b=>b.addEventListener('click',()=>editScriptForm(Number(b.dataset.editScript))))}
function editScriptForm(index=null){const item=index===null?{title:'',text:''}:state.scripts[index];openModal(index===null?'Thêm kịch bản':'Sửa kịch bản',`<div class="modal-fields">${fInput('Tên kịch bản','title','Ví dụ: Chào khách mới')}<label>Nội dung trả lời<textarea name="text" required>${esc(item.text)}</textarea></label><label>Hình ảnh (tuỳ chọn)<input type="file" name="imageFile" accept="image/*"></label><img id="scriptPreview" class="${item.image?'':'hidden'}" src="${esc(item.image||'')}" style="max-width:100px;border-radius:7px"></div>`,'Lưu kịch bản',async f=>{const file=$('[name=imageFile]').files[0];let image=item.image||'';if(file)image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const next={title:f.get('title'),text:f.get('text'),image};if(index===null)state.scripts.push(next);else state.scripts[index]=next;saveLocal();if(state.firebase)await saveRecord('settings',{scripts:state.scripts},'bot');closeModal();editScripts();showToast('Đã lưu kịch bản.')});$('[name=imageFile]')?.addEventListener('change',e=>{const f=e.target.files[0];if(f){const img=$('#scriptPreview');img.src=URL.createObjectURL(f);img.classList.remove('hidden')}})}
function editBanned(){if(!isManager())return showToast('Chỉ quản lý mới có thể chỉnh từ khoá cấm.','error');openModal('Từ khoá cấm',`<p>Mỗi dòng là một cụm từ. AI sẽ tránh sử dụng các cụm từ này trong gợi ý phản hồi.</p><div class="modal-fields"><label>Từ khoá<textarea name="words">${esc(state.banned.join('\n'))}</textarea></label></div>`,'Lưu từ khoá',async f=>{state.banned=f.get('words').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);saveLocal();if(state.firebase)await saveRecord('settings',{banned:state.banned},'bot');renderBotSummaries();closeModal();showToast('Đã cập nhật danh sách từ khoá.')})}
$('#manageScripts').addEventListener('click',editScripts);$('#editScripts').addEventListener('click',editScripts);$('#manageBanned').addEventListener('click',editBanned);$('#editBanned').addEventListener('click',editBanned);
function renderBotSummaries(){const bannedText=state.banned.length+' từ khoá',scriptText=state.scripts.length+' kịch bản'+(state.scripts.some(item=>item.image)?' · có hình ảnh':'');['#bannedSummary','#settingsBannedSummary'].forEach(selector=>{const el=$(selector);if(el)el.textContent=bannedText});['#scriptSummary','#settingsScriptSummary'].forEach(selector=>{const el=$(selector);if(el)el.textContent=scriptText})}
function renderConnectedPages(){const list=$('#connectedPages');if(!list)return;list.innerHTML=state.pages.map(page=>`<span class="page-connection"><i class="fb-round">f</i><span><b>${esc(page.pageName)}</b><small>${page.active?'Đang hoạt động':'Tạm dừng'}</small></span><span class="${page.active?'live-dot':'status status-neutral'}"></span></span>`).join('')||'<p class="muted">Chưa có Fanpage được kết nối.</p>'}
function connectPage(){if(!state.firebase)return showToast('Cần đăng nhập Firebase trước khi kết nối Fanpage.','error');openModal('Kết nối Fanpage',`<p>Nhập Page ID và Page Access Token. Token sẽ được gửi qua HTTPS, mã hoá trên máy chủ trước khi lưu.</p><div class="modal-fields">${fInput('Tên Fanpage','pageName','Tên trang')}${fInput('Facebook Page ID','pageId','ID trang quảng cáo')}${fInput('Page Access Token','pageToken','Page token','password')}${fSelect('Mô hình AI','model',[['gemini','Gemini'],['openai','ChatGPT']])}</div>`,'Kết nối',async f=>{const result=await callFunction('connectFacebookPage',{pageName:f.get('pageName'),pageId:f.get('pageId'),pageToken:f.get('pageToken'),model:f.get('model')});state.pages=[...state.pages.filter(p=>p.pageId!==f.get('pageId')),{pageId:f.get('pageId'),pageName:result.pageName||f.get('pageName'),model:f.get('model'),active:true}];renderConnectedPages();closeModal();showToast(result.message||'Đã kết nối Fanpage.')})}
$('#connectPage').addEventListener('click',connectPage);$('#settingsConnectPage').addEventListener('click',connectPage);$('#addPageInline').addEventListener('click',connectPage);

// Access control and user invitations.
$('#inviteUser').addEventListener('click',()=>{if(!isDirector())return showToast('Chỉ Giám đốc mới có thể mời thành viên.','error');openModal('Mời thành viên',`<p>Gửi lời mời để thành viên đăng ký bằng email công ty. Phân quyền có thể thay đổi sau khi tài khoản được xác minh.</p><div class="modal-fields">${fInput('Email công việc','email','ten@fbtq.vn','email')}${fSelect('Vai trò dự kiến','role',Object.entries(ROLE_NAMES).map(([k,v])=>[k,v]))}${fSelect('Phòng ban','department',[['Marketing','Marketing'],['Kinh doanh','Kinh doanh'],['Vận hành','Vận hành']])}</div>`,'Tạo lời mời',async f=>{const invite={email:f.get('email'),role:f.get('role'),department:f.get('department'),status:'invited',invitedBy:state.user?.uid};if(state.firebase)await saveRecord('invitations',invite);closeModal();showToast('Đã tạo lời mời. Chia sẻ liên kết đăng ký với thành viên.')})});
$('#editPermissions').addEventListener('click',()=>{if(!isDirector())return showToast('Chỉ Giám đốc mới có thể chỉnh phân quyền.','error');openModal('Phân quyền & vai trò',`<p>Nhập UID lấy trong Firebase Authentication hoặc email của tài khoản đã đăng ký. Website sẽ cập nhật vai trò trong hồ sơ Firestore và custom claim; người dùng cần đăng xuất rồi đăng nhập lại.</p><div class="modal-fields">${fInput('UID hoặc email tài khoản','uidOrEmail','Dán UID hoặc nhập email','text')}${fSelect('Vai trò mới','role',Object.entries(ROLE_NAMES).map(([k,v])=>[k,v]))}</div>`,'Cập nhật quyền',async f=>{try{const result=await callFunction('setUserRole',{uidOrEmail:String(f.get('uidOrEmail')||'').trim(),role:f.get('role')});closeModal();showToast(`Đã gán quyền ${roleName(result.role)}. Người dùng cần đăng xuất rồi đăng nhập lại.`)}catch(e){showToast(e.message||'Không thể cập nhật vai trò.','error')}})});
$('#metaConnect').addEventListener('click',()=>{navigate('settings');selectSetting('chatbot');showToast('Thiết lập Meta App trong mục Chatbot & Fanpage.')});

// Firebase and model settings.
$('#saveFirebase').addEventListener('click',async()=>{const c=configFromInputs();if(!validConfig(c)){showToast('Hãy điền đủ Firebase API Key, Auth Domain, Project ID và App ID.','error');return}localStorage.setItem('fbtq_firebase_config',JSON.stringify(c));firebaseBootPromise=firebaseInit(c,true);const ok=await firebaseBootPromise;if(ok&&window.location.protocol==='file:')showToast('Mở website qua HTTPS để Firebase Auth hoạt động.','error')});
$('#disconnectFirebase').addEventListener('click',async()=>{if(state.firebase)await state.firebase.authMod.signOut(state.firebase.auth);signOutToAuth();showToast('Đã đăng xuất khỏi workspace.')});
$('#saveAiSettings').addEventListener('click',async()=>{if(!isManager())return showToast('Chỉ quản lý mới có thể cấu hình mô hình AI.','error');const config={defaultModel:$('#defaultModel').value,brandVoice:$('#brandVoice').value};localStorage.setItem('fbtq_default_model',config.defaultModel);localStorage.setItem('fbtq_brand_voice',config.brandVoice);if(state.firebase)try{await saveRecord('settings',config,'bot')}catch(e){showToast(e.message,'error');return}const radio=$(`input[name="aiModel"][value="${config.defaultModel}"]`);if(radio){radio.checked=true;$$('.model-choice').forEach(x=>x.classList.toggle('selected',$('input',x)===radio))}$('#aiConfigStatus').textContent='Đã lưu lựa chọn mô hình. API keys được quản lý trên Firebase Functions.';showToast('Đã lưu lựa chọn mô hình.')});
$('#enableAutoReply').addEventListener('change',e=>showToast(e.target.checked?'Đã bật chế độ AI đề xuất. Nhân viên cần xác nhận trước khi gửi.':'Đã tắt AI đề xuất.'));

// Small utilities and initial setup.
$('#notificationBtn').addEventListener('click',()=>showToast('Bạn đã cập nhật các thông báo mới nhất.'));
$('#topProfile').addEventListener('click',()=>showToast(`${state.user?.name||state.user?.email||'Tài khoản'} · ${roleName(state.role)}`));
$('#copyGuide').setAttribute('aria-label','Hướng dẫn sao chép chỉ số Facebook Ads');
const savedFirebase=getSavedFirebaseConfig()||window.FBTQ_FIREBASE_CONFIG;if(validConfig(savedFirebase)){['apiKey','authDomain','projectId','appId'].forEach(k=>{const el=$('#fb'+k[0].toUpperCase()+k.slice(1));if(el)el.value=savedFirebase[k]});firebaseBootPromise=firebaseInit(savedFirebase)}
$('#defaultModel').value=localStorage.getItem('fbtq_default_model')||'gemini';$('#brandVoice').value=localStorage.getItem('fbtq_brand_voice')||'';const bootModel=$('#defaultModel').value,bootRadio=$(`input[name="aiModel"][value="${bootModel}"]`);if(bootRadio){bootRadio.checked=true;$$('.model-choice').forEach(x=>x.classList.toggle('selected',$('input',x)===bootRadio))}
